/**
 * Documentation generated by Claude
 * Purpose: Abstraction for reading, posting and removing campsite reviews.
 * Role / Design Pattern: Repository Pattern interface, so screens can be tested without Firestore.
 * Outstanding Issues: None.
 */
package com.example.campsitelottery

/**
 * Reads and writes campsite reviews. The real implementation is
 * [FirestoreReviewRepository]; tests use [InMemoryReviewRepository].
 *
 * Each operation invokes exactly one of its callbacks once it finishes.
 */
interface ReviewRepository {

    /**
     * Loads every review of [campsiteId].
     *
     * @param onSuccess receives the reviews, newest first.
     */
    fun getReviews(
        campsiteId: String,
        onSuccess: (List<Review>) -> Unit,
        onFailure: (Exception) -> Unit,
    )

    /**
     * Posts [userId]'s review of [campsiteId], replacing any earlier review from
     * the same user. The text is trimmed before it is saved.
     *
     * Fails if the text is blank or too long, the campsite doesn't exist, or the
     * user owns the campsite.
     *
     * @param authorName the name shown with the review.
     * @param onSuccess receives the saved review.
     */
    fun submitReview(
        campsiteId: String,
        userId: String,
        authorName: String,
        text: String,
        onSuccess: (Review) -> Unit,
        onFailure: (Exception) -> Unit,
    )

    /**
     * Removes [userId]'s review of [campsiteId], for admins taking down reviews
     * that violate the app policy.
     *
     * Fails if the review doesn't exist, or if it no longer matches [expected]
     * (the user reposted it after the admin read it).
     *
     * @param expected the review as the admin saw it, or null to remove whatever is stored.
     */
    fun removeReview(
        campsiteId: String,
        userId: String,
        expected: Review?,
        onSuccess: () -> Unit,
        onFailure: (Exception) -> Unit,
    )
}
